#!/usr/bin/env python3
import base64
import hashlib
import json
import os
import tempfile
import zipfile
import zlib

PBIX_PATH = "car_sales_dashboard.pbix"
EXPECTED_DATAMODEL_SHA256 = "06cad6bb69e51db0a572f1e95aedf97c80154adb5c2240146327c199ee4d63d3"
PAYLOAD = """"""

def build_zipinfo(item):
    info = zipfile.ZipInfo(item["name"], tuple(item["date_time"]))
    info.compress_type = item["compress_type"]
    info.external_attr = item["external_attr"]
    info.internal_attr = item["internal_attr"]
    info.create_system = item["create_system"]
    info.flag_bits = item["flag_bits"]
    info.extra = base64.b64decode(item["extra"])
    info.comment = base64.b64decode(item["comment"])
    return info

def main():
    target_entries = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))

    with zipfile.ZipFile(PBIX_PATH, "r") as source:
        datamodel = source.read("DataModel")
        datamodel_info = source.getinfo("DataModel")
        archive_comment = source.comment

    actual_hash = hashlib.sha256(datamodel).hexdigest()
    if actual_hash != EXPECTED_DATAMODEL_SHA256:
        raise RuntimeError(
            "DataModel differs from the uploaded final file; refusing to patch the PBIX. "
            f"Expected {EXPECTED_DATAMODEL_SHA256}, got {actual_hash}."
        )

    fd, temp_path = tempfile.mkstemp(suffix=".pbix")
    os.close(fd)

    try:
        with zipfile.ZipFile(temp_path, "w") as output:
            output.comment = archive_comment
            for item in target_entries:
                output.writestr(build_zipinfo(item), base64.b64decode(item["data"]))
            output.writestr(datamodel_info, datamodel)

        with zipfile.ZipFile(temp_path, "r") as check:
            if hashlib.sha256(check.read("DataModel")).hexdigest() != EXPECTED_DATAMODEL_SHA256:
                raise RuntimeError("DataModel verification failed after rebuilding.")
            for item in target_entries:
                expected = base64.b64decode(item["data"])
                actual = check.read(item["name"])
                if actual != expected:
                    raise RuntimeError(f"Verification failed for {item['name']}.")

        os.replace(temp_path, PBIX_PATH)
        print("Power BI report updated and verified successfully.")
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

if __name__ == "__main__":
    main()
